// Find duplicate names across categories
const allNames = [];
for (const [cat, arcs] of Object.entries(cats)) for (const a of arcs) allNames.push(a[0]);
const nameCounts = {};
for (const n of allNames) nameCounts[n] = (nameCounts[n]||0) + 1;

// Generate files
let count = 0;
for (const [category, archetypes] of Object.entries(cats)) {
  for (const a of archetypes) {
    const [name,desc,behavioral,stress,rest,always,never,unless,similarTo,oppositeOf,tags] = a;
    const obj = {
      name, type: "archetype", category, description: desc,
      behavioral_signature: behavioral, under_stress: stress, at_rest: rest,
      will_always: always, will_never: never, unless: unless,
      similar_to: similarTo.map(([archetype, threshold, context]) => ({ archetype, threshold, context })),
      opposite_of: oppositeOf, tags
    };
    const base = name.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/_+$/, '');
    const filename = (nameCounts[name] > 1 ? category + '_' : '') + base + '.json';
    fs.writeFileSync(path.join(outDir, filename), JSON.stringify(obj, null, 2));
    count++;
  }
}
console.log(`Generated ${count} archetype files in ${outDir}`);
